begin;
update public.questions set subject = 'Economy', topic = 'Macro Concepts, National Income & Inflation', type = 'statement_based', difficulty = 'hard', body = 'With reference to the estimates of national income in India, consider the following statements:', body_hi = 'भारत में राष्ट्रीय आय के अनुमानों के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 2 and 3 are correct. GDP at market prices is GVA at basic prices plus product taxes minus product subsidies, so when GDP grows more slowly than GVA, the net-tax component must have grown more slowly than GVA. In April-June 2026 the National Statistics Office put real GVA growth at 8.2 per cent and real GDP growth at 7.8 per cent. The implicit deflator is nominal GDP divided by real GDP; nominal growth of 10.3 per cent against real growth of 7.8 per cent means it rose, by about 2.3 per cent. Statement 1 is wrong: the two are equal in the base year, and for any year before the base year, when prices were lower, constant-price GDP is the larger. The new series has 2022-23 as its base year, so the figures for 2021-22 and earlier sit above their current-price values. The ''never'' is the trap.', explanation_hi = 'कथन 2 और 3 सही हैं। बाज़ार कीमतों पर जीडीपी आधार कीमतों पर जीवीए में उत्पाद कर जोड़कर और उत्पाद सब्सिडी घटाकर निकलता है, इसलिए जब जीडीपी जीवीए से धीमे बढ़े, तो शुद्ध-कर घटक जीवीए से धीमे बढ़ा होगा। अप्रैल-जून 2026 में राष्ट्रीय सांख्यिकी कार्यालय ने वास्तविक जीवीए वृद्धि 8.2 प्रतिशत और वास्तविक जीडीपी वृद्धि 7.8 प्रतिशत आँकी। अंतर्निहित अपस्फीतिकारक नाममात्र जीडीपी को वास्तविक जीडीपी से भाग देकर निकलता है; 7.8 प्रतिशत वास्तविक वृद्धि के सामने 10.3 प्रतिशत नाममात्र वृद्धि का अर्थ है कि यह लगभग 2.3 प्रतिशत बढ़ा। कथन 1 ग़लत है: आधार वर्ष में दोनों बराबर होते हैं, और आधार वर्ष से पहले के किसी भी वर्ष के लिए, जब कीमतें कम थीं, स्थिर कीमतों वाला जीडीपी बड़ा होता है। नई शृंखला का आधार वर्ष 2022-23 है, इसलिए 2021-22 और उससे पहले के आँकड़े अपने चालू-कीमत मूल्यों से ऊपर रहते हैं। ‘कभी नहीं’ ही जाल है।', concept_group_id = 'ca-t3-eco-gdp-q1-nominal-real-gva-net-taxes', source_citation = 'Ministry of Statistics and Programme Implementation, Press Note on Estimates of GDP for Q1 of 2026-27 (31 August 2026); NCERT, Introductory Macroeconomics (Class XII), Chapter 2 (National Income Accounting).', question_data = '{"statements": ["GDP at constant prices can never exceed GDP at current prices.", "If nominal GDP grows faster than real GDP, the implicit GDP deflator has risen.", "If real GVA grows faster than real GDP in a quarter, net product taxes have grown more slowly than GVA in that quarter."], "statements_hi": ["स्थिर कीमतों पर जीडीपी कभी भी चालू कीमतों पर जीडीपी से अधिक नहीं हो सकता।", "यदि नाममात्र जीडीपी वास्तविक जीडीपी से तेज़ बढ़े, तो अंतर्निहित जीडीपी अपस्फीतिकारक बढ़ा है।", "यदि किसी तिमाही में वास्तविक जीवीए वास्तविक जीडीपी से तेज़ बढ़े, तो उस तिमाही में शुद्ध उत्पाद कर जीवीए से धीमे बढ़े हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "b", "body": "3 only", "body_hi": "केवल 3", "isCorrect": false}, {"id": "c", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": true}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-gdp-q1-nominal-real-gva-net-taxes') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'External Sector & International Institutions', type = 'assertion_reason', difficulty = 'medium', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only Statement II is correct, and it explains Statement I. In April-June 2026 India''s current account deficit was only US$ 4.2 billion, 0.5 per cent of GDP, yet the capital account showed a net outflow of about US$ 5.5 billion instead of financing it. The overall balance of payments was therefore in deficit by about US$ 8.1 billion, met by drawing down reserves by that amount. Statement III is wrong: changes in the rupee value of gold and foreign currencies held in the reserves are valuation changes, not transactions, and are not recorded in the balance of payments at all. That is why reserves fell by about US$ 22.5 billion in total in that quarter but by only US$ 8.1 billion on a balance-of-payments basis.', explanation_hi = 'केवल कथन II सही है, और यह कथन I की व्याख्या करता है। अप्रैल-जून 2026 में भारत का चालू खाता घाटा केवल 4.2 अरब अमेरिकी डॉलर, जीडीपी का 0.5 प्रतिशत, था, फिर भी पूँजी खाते ने उसकी पूर्ति करने के बजाय लगभग 5.5 अरब डॉलर का शुद्ध बहिर्वाह दिखाया। इसलिए समग्र भुगतान संतुलन लगभग 8.1 अरब डॉलर के घाटे में रहा, जिसकी पूर्ति उतने ही भंडार निकालकर हुई। कथन III ग़लत है: भंडार में रखे सोने और विदेशी मुद्राओं के मूल्य में परिवर्तन मूल्यांकन परिवर्तन हैं, लेन-देन नहीं, और भुगतान संतुलन में दर्ज ही नहीं होते। इसी कारण उस तिमाही में भंडार कुल मिलाकर लगभग 22.5 अरब डॉलर घटे, पर भुगतान संतुलन के आधार पर केवल 8.1 अरब डॉलर।', concept_group_id = 'ca-t3-eco-bop-q1-cad-capital-outflow-reserves-si', source_citation = 'Reserve Bank of India, Developments in India''s Balance of Payments during the First Quarter (April-June) of 2026-27 (1 September 2026); NCERT, Introductory Macroeconomics (Class XII), Chapter 6 (Open Economy Macroeconomics).', question_data = '{"assertion": "A country''s foreign exchange reserves, measured on a balance-of-payments basis, can fall in a quarter even when its current account deficit is below one per cent of GDP.", "assertion_hi": "किसी देश के विदेशी मुद्रा भंडार, भुगतान संतुलन के आधार पर मापे जाने पर, किसी तिमाही में तब भी घट सकते हैं जब उसका चालू खाता घाटा जीडीपी के एक प्रतिशत से कम हो।", "reason": "Reserves fall on a balance-of-payments basis when net capital flows do not cover the current account deficit.", "reason_hi": "भुगतान संतुलन के आधार पर भंडार तब घटते हैं जब शुद्ध पूँजी प्रवाह चालू खाते के घाटे की पूर्ति नहीं करते।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference", "reason_2": "Changes in the value of the gold and foreign currencies held in the reserves are recorded in the capital account of the balance of payments.", "reason_2_hi": "भंडार में रखे सोने और विदेशी मुद्राओं के मूल्य में परिवर्तन भुगतान संतुलन के पूँजी खाते में दर्ज होते हैं।", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": false}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": true}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-bop-q1-cad-capital-outflow-reserves-si') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Money, Banking & Monetary Policy', type = 'statement_based', difficulty = 'medium', body = 'With reference to the Merchant Discount Rate (MDR) on digital payments in India, consider the following statements:', body_hi = 'भारत में डिजिटल भुगतानों पर मर्चेंट डिस्काउंट रेट (एमडीआर) के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. Section 10A, inserted in the Payment and Settlement Systems Act in 2019, barred banks and system providers from charging anyone for payments made through the electronic modes prescribed under the Income-tax Act, which is why UPI and RuPay debit payments carried no MDR from January 2020; the costs of running UPI fell on banks and payment firms, partly met by a government incentive scheme. Parliament amended the section in the Monsoon Session of 2026 to allow an MDR of 0.4 per cent, capped at ₹300, on person-to-merchant payments above ₹2,000; it was to apply from 15 October 2026, but NPCI deferred it until after Diwali, to a date to be notified. Statement 1 is wrong: MDR is borne by the merchant, deducted by the merchant''s bank and shared with the customer''s bank and the network; the customer pays nothing extra. Statement 3 is wrong: person-to-person transfers stay free, and so do payments to merchants up to ₹2,000, which make up most UPI transactions.', explanation_hi = 'केवल कथन 2 सही है। 2019 में भुगतान और निपटान प्रणाली अधिनियम में जोड़ी गई धारा 10क ने बैंकों और प्रणाली प्रदाताओं को आयकर अधिनियम के अंतर्गत निर्धारित इलेक्ट्रॉनिक माध्यमों से किए गए भुगतानों पर किसी से भी शुल्क लेने से रोका, इसी कारण जनवरी 2020 से यूपीआई और रूपे डेबिट भुगतानों पर कोई एमडीआर नहीं था; यूपीआई चलाने की लागत बैंकों और भुगतान कंपनियों पर पड़ी, जिसका कुछ भाग एक सरकारी प्रोत्साहन योजना से पूरा हुआ। संसद ने 2026 के मानसून सत्र में धारा में संशोधन करके ₹2,000 से अधिक के व्यक्ति-से-व्यापारी भुगतानों पर 0.4 प्रतिशत, अधिकतम ₹300, के एमडीआर की अनुमति दी; इसे 15 अक्टूबर 2026 से लागू होना था, पर एनपीसीआई ने इसे दिवाली के बाद, अलग से अधिसूचित होने वाली तिथि तक, टाल दिया। कथन 1 ग़लत है: एमडीआर व्यापारी वहन करता है, इसे व्यापारी का बैंक काटता है और ग्राहक के बैंक तथा नेटवर्क के साथ बाँटता है; ग्राहक कुछ अतिरिक्त नहीं देता। कथन 3 ग़लत है: व्यक्ति-से-व्यक्ति अंतरण निःशुल्क बने रहते हैं, और ₹2,000 तक के व्यापारी भुगतान भी, जो यूपीआई लेन-देन का अधिकांश भाग हैं।', concept_group_id = 'ca-t3-eco-upi-mdr-p2m-2000-section-10a', source_citation = 'Department of Financial Services, FAQs on Merchant Discount Rate on select UPI (P2M) transactions (September 2026); NPCI, deferment of MDR on select P2M transactions (October 2026); Payment and Settlement Systems Act, 2007, section 10A.', question_data = '{"statements": ["MDR is a fee that the customer pays to his or her own bank on each payment.", "Allowing MDR on UPI payments required an amendment to the Payment and Settlement Systems Act, 2007.", "Person-to-person transfers through UPI attract MDR above a threshold value."], "statements_hi": ["एमडीआर वह शुल्क है जो ग्राहक हर भुगतान पर अपने बैंक को देता है।", "यूपीआई भुगतानों पर एमडीआर की अनुमति देने के लिए भुगतान और निपटान प्रणाली अधिनियम, 2007 में संशोधन आवश्यक था।", "यूपीआई से व्यक्ति-से-व्यक्ति अंतरण पर एक सीमा-मूल्य से ऊपर एमडीआर लगता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "c", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}, {"id": "d", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-upi-mdr-p2m-2000-section-10a') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Inclusive Growth, Welfare & Demography', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Employees'' Provident Fund Organisation (EPFO) and the schemes it runs:', body_hi = 'कर्मचारी भविष्य निधि संगठन (ईपीएफ़ओ) और उसके द्वारा चलाई जाने वाली योजनाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The wage ceiling decides who must be covered: raised from ₹15,000 to ₹25,000 a month from 17 September 2026, its first revision since 2014, it brought about 51 lakh more workers under compulsory coverage; above it, coverage needs the consent of employer and employee. Of the employer''s 12 per cent contribution, 8.33 per cent of wages up to the ceiling goes to the Employees'' Pension Scheme, 1995, so a higher ceiling also raises pension contributions. Statement 3 is wrong: the EPFO, a statutory body under the Employees'' Provident Funds and Miscellaneous Provisions Act, 1952, is governed by a tripartite Central Board of Trustees chaired by the Union Minister of Labour and Employment, under whose ministry it functions.', explanation_hi = 'कथन 1 और 2 सही हैं। वेतन-सीमा तय करती है कि किसे अनिवार्य रूप से शामिल होना है: 17 सितंबर 2026 से ₹15,000 से बढ़ाकर ₹25,000 प्रति माह की गई, जो 2014 के बाद इसका पहला संशोधन है, इसने लगभग 51 लाख और श्रमिकों को अनिवार्य कवरेज में ला दिया; उससे ऊपर कवरेज के लिए नियोक्ता और कर्मचारी की सहमति चाहिए। नियोक्ता के 12 प्रतिशत अंशदान में से सीमा तक के वेतन का 8.33 प्रतिशत कर्मचारी पेंशन योजना, 1995 में जाता है, इसलिए ऊँची सीमा पेंशन अंशदान भी बढ़ाती है। कथन 3 ग़लत है: कर्मचारी भविष्य निधि और प्रकीर्ण उपबंध अधिनियम, 1952 के अंतर्गत सांविधिक निकाय ईपीएफ़ओ का संचालन एक त्रिपक्षीय केंद्रीय न्यासी बोर्ड करता है, जिसके अध्यक्ष केंद्रीय श्रम और रोज़गार मंत्री हैं, और यह उन्हीं के मंत्रालय के अधीन कार्य करता है।', concept_group_id = 'ca-t3-eco-epfo-wage-ceiling-25000-eps-voluntary', source_citation = 'Ministry of Labour and Employment and EPFO, notification raising the wage ceiling to ₹25,000 (September 2026); Employees'' Provident Funds and Miscellaneous Provisions Act, 1952; Employees'' Pension Scheme, 1995.', question_data = '{"statements": ["Membership is compulsory for employees whose pay is within a wage ceiling notified by the Government, while those above it may join voluntarily.", "A part of the employer''s contribution goes to the Employees'' Pension Scheme rather than to the employee''s provident fund account.", "The EPFO functions under the Ministry of Finance."], "statements_hi": ["सरकार द्वारा अधिसूचित वेतन-सीमा के भीतर वेतन पाने वाले कर्मचारियों के लिए सदस्यता अनिवार्य है, जबकि उससे ऊपर वाले स्वेच्छा से जुड़ सकते हैं।", "नियोक्ता के अंशदान का एक भाग कर्मचारी के भविष्य निधि खाते के बजाय कर्मचारी पेंशन योजना में जाता है।", "ईपीएफ़ओ वित्त मंत्रालय के अधीन कार्य करता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": true}, {"id": "b", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "c", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-epfo-wage-ceiling-25000-eps-voluntary') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Industry, Infrastructure, Energy & Services', type = 'mcq', difficulty = 'medium', body = '''Samudra Manthan'', a national scheme approved by the Union Cabinet, is best described as', body_hi = 'केंद्रीय मंत्रिमंडल द्वारा स्वीकृत राष्ट्रीय योजना ‘समुद्र मंथन’ का सबसे उपयुक्त वर्णन है', explanation = 'Samudra Manthan, the National Offshore Exploration Scheme of the Ministry of Petroleum and Natural Gas (outlay ₹84,084 crore to 2030-31), is funded wholly by the Centre. It pays for basin-wide 2D and 3D seismic surveys, a national data repository and common offshore facilities, so that deepwater and frontier blocks can be offered under the Open Acreage Licensing Policy with data in hand. The aim, subject to discoveries, is to raise domestic oil and gas output from about 62 to 80 million tonnes of oil equivalent a year, since India imports most of its crude. Mining polymetallic nodules under the contract with the International Seabed Authority belongs to the Deep Ocean Mission of the Ministry of Earth Sciences. No Centrally Sponsored desalination scheme of that name exists. Power from the ocean''s temperature gradient is ocean thermal energy conversion, which the National Institute of Ocean Technology is piloting in Lakshadweep.', explanation_hi = 'समुद्र मंथन, पेट्रोलियम और प्राकृतिक गैस मंत्रालय की राष्ट्रीय अपतटीय अन्वेषण योजना (2030-31 तक ₹84,084 करोड़ का परिव्यय), का पूरा व्यय केंद्र वहन करता है। यह बेसिन-व्यापी 2डी और 3डी भूकंपीय सर्वेक्षणों, एक राष्ट्रीय डेटा भंडार और साझा अपतटीय सुविधाओं का व्यय वहन करती है, ताकि गहरे जल और सीमांत ब्लॉक खुली एकरेज लाइसेंसिंग नीति के अंतर्गत आँकड़ों के साथ दिए जा सकें। लक्ष्य, खोजों के अधीन, घरेलू तेल और गैस उत्पादन को लगभग 62 से बढ़ाकर 80 मिलियन टन तेल समतुल्य प्रति वर्ष करना है, क्योंकि भारत अपने कच्चे तेल का अधिकांश आयात करता है। अंतरराष्ट्रीय समुद्र तल प्राधिकरण के साथ अनुबंध के अंतर्गत बहुधात्विक पिंडों का खनन पृथ्वी विज्ञान मंत्रालय के डीप ओशन मिशन का भाग है। इस नाम की कोई केंद्र प्रायोजित विलवणीकरण योजना नहीं है। महासागर के तापांतर से बिजली महासागरीय तापीय ऊर्जा रूपांतरण है, जिसका प्रायोगिक संयंत्र राष्ट्रीय महासागर प्रौद्योगिकी संस्थान लक्षद्वीप में बना रहा है।', concept_group_id = 'ca-t3-eco-samudra-manthan-central-sector-oalp', source_citation = 'Cabinet decision and PIB, ''Samudra Manthan'' National Offshore Exploration Scheme (31 July 2026); Ministry of Petroleum and Natural Gas, Hydrocarbon Exploration and Licensing Policy (2016); Ministry of Earth Sciences, Deep Ocean Mission.', question_data = '{"craft": "linkage", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "a mission to mine polymetallic nodules from the Central Indian Ocean Basin under India''s contract with the International Seabed Authority", "body_hi": "अंतरराष्ट्रीय समुद्र तल प्राधिकरण के साथ भारत के अनुबंध के अंतर्गत मध्य हिंद महासागर बेसिन से बहुधात्विक पिंडों के खनन का एक मिशन", "isCorrect": false}, {"id": "b", "body": "a Centrally Sponsored Scheme through which the coastal States build desalination plants to supply drinking water to island territories", "body_hi": "एक केंद्र प्रायोजित योजना जिसके माध्यम से तटीय राज्य द्वीपीय क्षेत्रों को पेयजल देने के लिए विलवणीकरण संयंत्र बनाते हैं", "isCorrect": false}, {"id": "c", "body": "a programme to generate electricity from the temperature difference between warm surface water and cold deep water around islands", "body_hi": "द्वीपों के आसपास गर्म सतही जल और ठंडे गहरे जल के तापांतर से बिजली बनाने का एक कार्यक्रम", "isCorrect": false}, {"id": "d", "body": "a Central Sector Scheme that pays for seismic surveys and data to open deepwater and frontier offshore areas to oil and gas exploration", "body_hi": "भूकंपीय सर्वेक्षणों और आँकड़ों से गहरे जल और सीमांत अपतटीय क्षेत्रों को तेल-गैस अन्वेषण हेतु खोलने वाली केंद्रीय क्षेत्र योजना", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-samudra-manthan-central-sector-oalp') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Agriculture & Food Economy', type = 'statement_based', difficulty = 'medium', body = 'The Government has adopted a new investment policy for urea that assures new gas-based plants a return on equity within a band. Which of the following explain why such an assurance is needed?', body_hi = 'सरकार ने यूरिया के लिए एक नई निवेश नीति अपनाई है जो गैस-आधारित नए संयंत्रों को एक सीमा के भीतर इक्विटी पर प्रतिफल का आश्वासन देती है। निम्नलिखित में से कौन-से कारण बताते हैं कि ऐसा आश्वासन क्यों आवश्यक है?', explanation = 'Statements 1 and 3 are correct. Because urea''s maximum retail price is fixed and the subsidy covers the gap between cost and price, an investor''s return depends on the government''s pricing formula, not on the market; the National Investment Policy for Urea-2026 therefore separates fixed from variable costs, assures a return on equity of 12-16 per cent and shares foreign-exchange risk, to draw in eight or nine new plants. The 2012 policy it succeeds had lapsed in 2019. Imports still meet a sizeable part of demand, and new domestic capacity is meant to cut them. Statement 2 reverses the facts: natural gas is the most energy-efficient and cleanest feedstock for ammonia and urea, which is why the naphtha- and fuel-oil-based units were converted to gas and energy norms per tonne were tightened under the New Urea Policy, 2015. The assured return answers the price control and the long payback of a large plant, not a higher energy cost.', explanation_hi = 'कथन 1 और 3 सही हैं। चूँकि यूरिया का अधिकतम खुदरा मूल्य तय है और सब्सिडी लागत तथा मूल्य के अंतर की पूर्ति करती है, निवेशक का प्रतिफल बाज़ार पर नहीं, सरकार के मूल्य-सूत्र पर निर्भर करता है; इसलिए यूरिया के लिए राष्ट्रीय निवेश नीति-2026 स्थिर और परिवर्ती लागतों को अलग करती है, 12-16 प्रतिशत इक्विटी प्रतिफल का आश्वासन देती है और विदेशी मुद्रा जोखिम साझा करती है, ताकि आठ-नौ नए संयंत्र आकर्षित हों। इसकी पूर्ववर्ती 2012 की नीति 2019 में समाप्त हो गई थी। आयात अब भी माँग का बड़ा भाग पूरा करता है, और नई घरेलू क्षमता का उद्देश्य उसे घटाना है। कथन 2 तथ्यों को उलट देता है: प्राकृतिक गैस अमोनिया और यूरिया के लिए सबसे ऊर्जा-दक्ष और स्वच्छ फ़ीडस्टॉक है, इसी कारण नैफ़्था और ईंधन-तेल आधारित इकाइयाँ गैस पर बदली गईं और नई यूरिया नीति, 2015 के अंतर्गत प्रति टन ऊर्जा मानदंड कड़े किए गए। सुनिश्चित प्रतिफल मूल्य-नियंत्रण और बड़े संयंत्र की लंबी वसूली-अवधि का उत्तर है, ऊँची ऊर्जा लागत का नहीं।', concept_group_id = 'ca-t3-eco-nipu-2026-roe-band-12-16', source_citation = 'Cabinet Committee on Economic Affairs and PIB, National Investment Policy for Urea-2026 (15 July 2026); Department of Fertilizers, New Investment Policy, 2012 and New Urea Policy, 2015.', question_data = '{"statements": ["A part of India''s urea requirement is met by imports, which exposes the subsidy bill to swings in world prices.", "Gas-based plants use more energy per tonne of urea than the older naphtha- and fuel-oil-based plants, so they need a higher assured return.", "The retail price of urea is fixed by the Government, so a new plant cannot recover its costs through the market price alone."], "statements_hi": ["भारत की यूरिया आवश्यकता का एक भाग आयात से पूरा होता है, जिससे सब्सिडी बिल विश्व कीमतों के उतार-चढ़ाव के प्रति खुला रहता है।", "गैस-आधारित संयंत्र पुराने नैफ़्था और ईंधन-तेल आधारित संयंत्रों से प्रति टन यूरिया अधिक ऊर्जा लेते हैं, इसलिए उन्हें ऊँचे सुनिश्चित प्रतिफल की आवश्यकता है।", "यूरिया का खुदरा मूल्य सरकार तय करती है, इसलिए नया संयंत्र केवल बाज़ार मूल्य से अपनी लागत नहीं निकाल सकता।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "application", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": true}, {"id": "c", "body": "3 only", "body_hi": "केवल 3", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-nipu-2026-roe-band-12-16') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Agriculture & Food Economy', type = 'assertion_reason', difficulty = 'medium', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct, and Statement II explains Statement I. Wheat''s MSP rose by only ₹25, to ₹2,610 a quintal, while safflower rose by ₹675 to ₹7,215 and lentil, rapeseed-mustard and barley by 6-7 per cent. India has large wheat stocks but imports much of its edible oil and some of its pulses, and the Mission for Aatmanirbharta in Pulses and the edible-oil mission aim to cut those imports; since sowing decisions follow expected prices, the Government announces MSPs before sowing and widens the gap in favour of the crops it wants grown. Since 2018-19 every rabi MSP has carried a margin of at least 50 per cent over the all-India weighted average cost of production; in 2027-28 the margins ran from 50 per cent upwards.', explanation_hi = 'दोनों कथन सही हैं, और कथन II कथन I की व्याख्या करता है। गेहूँ का एमएसपी केवल ₹25 बढ़कर ₹2,610 प्रति क्विंटल हुआ, जबकि कुसुम ₹675 बढ़कर ₹7,215 हुआ और मसूर, सरसों-रेपसीड तथा जौ 6-7 प्रतिशत बढ़े। भारत के पास गेहूँ के बड़े भंडार हैं पर वह अपने खाद्य तेल का बड़ा भाग और कुछ दालें आयात करता है, और दालों में आत्मनिर्भरता मिशन तथा खाद्य तेल मिशन का उद्देश्य इन आयातों को घटाना है; चूँकि बुवाई के निर्णय अपेक्षित कीमतों पर चलते हैं, सरकार बुवाई से पहले एमएसपी घोषित करती है और जिन फ़सलों को उगवाना चाहती है उनके पक्ष में अंतर बढ़ाती है। 2018-19 से हर रबी एमएसपी में उत्पादन की अखिल भारतीय भारित औसत लागत पर कम से कम 50 प्रतिशत का मार्जिन रहा है; 2027-28 में मार्जिन 50 प्रतिशत से ऊपर की ओर रहे।', concept_group_id = 'ca-t3-eco-rabi-msp-2027-28-margins-safflower', source_citation = 'Cabinet Committee on Economic Affairs and PIB, MSP for Rabi Crops for Marketing Season 2027-28 (30 September 2026); Commission for Agricultural Costs and Prices; Department of Agriculture and Farmers Welfare, Mission for Aatmanirbharta in Pulses.', question_data = '{"assertion": "In the minimum support prices fixed for the rabi crops of the 2027-28 marketing season, wheat received the smallest increase of all the rabi crops.", "assertion_hi": "विपणन मौसम 2027-28 की रबी फ़सलों के लिए तय न्यूनतम समर्थन मूल्यों में सभी रबी फ़सलों में सबसे कम वृद्धि गेहूँ को मिली।", "reason": "Relative support prices are being used to draw area away from wheat towards oilseeds and pulses, which India imports.", "reason_hi": "सापेक्ष समर्थन मूल्यों का उपयोग रकबे को गेहूँ से हटाकर तिलहन और दालों की ओर ले जाने के लिए किया जा रहा है, जिनका भारत आयात करता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "application", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-rabi-msp-2027-28-margins-safflower') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Taxation & Fiscal Federalism', type = 'statement_based', difficulty = 'hard', body = 'With reference to the taxation of minerals in India, consider the following statements:', body_hi = 'भारत में खनिजों पर कराधान के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. Entry 50 of the State List reads ''Taxes on mineral rights subject to any limitations imposed by Parliament by law relating to mineral development'', and Entry 54 of the Union List covers the regulation of mines and mineral development. In 2024 a nine-judge bench of the Supreme Court held 8:1 that the States may tax mineral rights and mineral-bearing land, and several States then imposed new and retrospective levies; the 2026 amendment, using the power Entry 50 reserves to Parliament, sets limits on such levies. Statement 2 is wrong: the amendment limits the levies rather than abolishing the States'' power. The States argue that it cuts into a source of revenue the Court had confirmed; the Centre argues that uniform limits keep mineral auctions and investment predictable.', explanation_hi = 'कथन 1 और 3 सही हैं। राज्य सूची की प्रविष्टि 50 में है ‘खनिज विकास से संबंधित कानून द्वारा संसद की लगाई किन्हीं सीमाओं के अधीन खनिज अधिकारों पर कर’, और संघ सूची की प्रविष्टि 54 खानों के विनियमन और खनिज विकास को समेटती है। 2024 में सर्वोच्च न्यायालय की नौ न्यायाधीशों की पीठ ने 8:1 से कहा कि राज्य खनिज अधिकारों और खनिज-युक्त भूमि पर कर लगा सकते हैं, जिसके बाद कई राज्यों ने नए और पूर्वव्यापी उद्ग्रहण लगाए; 2026 का संशोधन, प्रविष्टि 50 द्वारा संसद के लिए सुरक्षित शक्ति का उपयोग कर, ऐसे उद्ग्रहणों पर सीमाएँ लगाता है। कथन 2 ग़लत है: संशोधन राज्यों की शक्ति समाप्त नहीं करता, उद्ग्रहणों को सीमित करता है। राज्यों का तर्क है कि यह राजस्व के उस स्रोत में कटौती करता है जिसकी न्यायालय ने पुष्टि की थी; केंद्र का तर्क है कि एकसमान सीमाएँ खनिज नीलामियों और निवेश को अनुमानित रखती हैं।', concept_group_id = 'ca-t3-eco-mmdr-2026-state-levies-entry-50', source_citation = 'Mines and Minerals (Development and Regulation) Amendment Act, 2026; Constitution of India, Seventh Schedule, List I Entry 54 and List II Entry 50; Supreme Court of India, Mineral Area Development Authority v. Steel Authority of India (2024).', question_data = '{"statements": ["Taxes on mineral rights are in the State List, subject to any limitations imposed by Parliament by law relating to mineral development.", "After the Mines and Minerals (Development and Regulation) Amendment Act, 2026, a State can no longer levy any tax on mineral-bearing land.", "The amendment was passed after the Supreme Court had upheld the States'' power to tax mineral rights and mineral-bearing land."], "statements_hi": ["खनिज अधिकारों पर कर राज्य सूची में हैं, खनिज विकास से संबंधित कानून द्वारा संसद की लगाई किन्हीं सीमाओं के अधीन।", "खान और खनिज (विकास और विनियमन) संशोधन अधिनियम, 2026 के बाद कोई राज्य खनिज-युक्त भूमि पर अब कोई भी कर नहीं लगा सकता।", "यह संशोधन सर्वोच्च न्यायालय द्वारा खनिज अधिकारों और खनिज-युक्त भूमि पर कर लगाने की राज्यों की शक्ति बरकरार रखे जाने के बाद पारित हुआ।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "3 only", "body_hi": "केवल 3", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": true}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-mmdr-2026-state-levies-entry-50') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'External Sector & International Institutions', type = 'statement_based', difficulty = 'medium', body = 'In the context of the tariffs imposed by the United States on imports from India in 2026, consider the following statements:', body_hi = '2026 में संयुक्त राज्य अमेरिका द्वारा भारत से आयात पर लगाए गए शुल्कों के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. After the US Supreme Court struck down the earlier ''reciprocal tariffs'' in February 2026, Washington imposed a temporary surcharge under Section 122, which caps such balance-of-payments duties at 150 days; as it lapsed, the US Trade Representative took action under Section 301 against some 60 economies over their controls on imports made with forced labour. Statement 3 is wrong: economies that had adopted and enforced a ban on such imports were put in a 10 per cent tier and the rest at 12.5 per cent, and India, which had amended its Foreign Trade Policy in June 2026 to prohibit imports made with forced or compulsory labour, got the lower rate, while contesting the basis of the action. Statement 1 is wrong: Section 301 is a unilateral US remedy against foreign practices it finds unreasonable; anti-dumping duties answer imports priced below normal value and need a finding of injury to the domestic industry.', explanation_hi = 'केवल कथन 2 सही है। फ़रवरी 2026 में अमेरिकी सर्वोच्च न्यायालय द्वारा पहले के ‘पारस्परिक शुल्क’ रद्द किए जाने के बाद वॉशिंगटन ने धारा 122 के अंतर्गत एक अस्थायी अधिभार लगाया, जो भुगतान-संतुलन संबंधी ऐसे शुल्कों को 150 दिनों तक सीमित रखती है; उसके समाप्त होते ही अमेरिकी व्यापार प्रतिनिधि ने बलात श्रम से बने आयात पर नियंत्रणों को लेकर लगभग 60 अर्थव्यवस्थाओं के विरुद्ध धारा 301 के अंतर्गत कार्रवाई की। कथन 3 ग़लत है: ऐसे आयात पर प्रतिबंध अपनाने और लागू करने वाली अर्थव्यवस्थाएँ 10 प्रतिशत की श्रेणी में और शेष 12.5 प्रतिशत पर रखी गईं, और भारत, जिसने जून 2026 में बलात या अनिवार्य श्रम से बने आयात पर रोक के लिए अपनी विदेश व्यापार नीति में संशोधन किया था, निचली दर पर रहा, यद्यपि उसने कार्रवाई के आधार को चुनौती दी। कथन 1 ग़लत है: धारा 301 उन विदेशी व्यवहारों के विरुद्ध अमेरिका का एकतरफ़ा उपाय है जिन्हें वह अनुचित पाता है; पाटनरोधी शुल्क सामान्य मूल्य से कम कीमत वाले आयात का उत्तर हैं और उनके लिए घरेलू उद्योग को क्षति का निष्कर्ष आवश्यक है।', concept_group_id = 'ca-t3-eco-us-section-301-forced-labour-10-tier', source_citation = 'Ministry of Commerce and Industry, Foreign Trade Policy amendment prohibiting imports made with forced labour (June 2026); Office of the United States Trade Representative, Section 301 action on forced-labour import controls (July 2026); WTO Anti-Dumping Agreement.', question_data = '{"statements": ["The tariffs were imposed as anti-dumping duties after an injury investigation under the rules of the World Trade Organization.", "A balance-of-payments surcharge under Section 122 of the US Trade Act of 1974 cannot stay in force for more than 150 days without the approval of the US Congress.", "India was charged the higher of two rates because it had not restricted imports of goods made with forced labour."], "statements_hi": ["शुल्क विश्व व्यापार संगठन के नियमों के अंतर्गत क्षति-जाँच के बाद पाटनरोधी शुल्क के रूप में लगाए गए।", "अमेरिकी व्यापार अधिनियम, 1974 की धारा 122 के अंतर्गत भुगतान-संतुलन अधिभार अमेरिकी कांग्रेस की स्वीकृति के बिना 150 दिनों से अधिक लागू नहीं रह सकता।", "भारत पर दो दरों में से ऊँची दर लगी क्योंकि उसने बलात श्रम से बनी वस्तुओं के आयात पर रोक नहीं लगाई थी।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "b", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "c", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "d", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-us-section-301-forced-labour-10-tier') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Budget, Deficits & Public Debt', type = 'statement_based', difficulty = 'medium', body = 'With reference to the Ways and Means Advances (WMA) given by the Reserve Bank of India to State Governments, consider the following statements:', body_hi = 'रिज़र्व बैंक द्वारा राज्य सरकारों को दिए जाने वाले अर्थोपाय अग्रिमों (डब्ल्यूएमए) के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. As banker to the States under agreements with them, the Reserve Bank first allows a Special Drawing Facility secured against the States'' investments in the Consolidated Sinking Fund and other reserve funds, then WMA -- short-term advances to bridge temporary gaps between receipts and payments, not to finance a deficit. Statement 1 is wrong: beyond the WMA a State may run an overdraft for a limited number of days; the Reserve Bank''s advisory committee chaired by I.S.N. Prasad proposed in September 2026 to tighten this to 10 consecutive days and 30 days a quarter. Statement 3 is wrong: the limits are fixed by the Reserve Bank, revised on the advice of such committees; this one proposed raising the aggregate from ₹61,008 crore to ₹67,839 crore and basing each State''s limit on adjusted revenue receipts rather than expenditure.', explanation_hi = 'केवल कथन 2 सही है। राज्यों के साथ समझौतों के अंतर्गत उनके बैंकर के रूप में रिज़र्व बैंक पहले समेकित निक्षेप निधि और अन्य आरक्षित निधियों में राज्यों के निवेश के बदले विशेष आहरण सुविधा देता है, फिर डब्ल्यूएमए -- प्राप्तियों और भुगतानों के अस्थायी अंतर को पाटने वाले अल्पकालिक अग्रिम, घाटे के वित्तपोषण के लिए नहीं। कथन 1 ग़लत है: डब्ल्यूएमए से आगे कोई राज्य सीमित दिनों के लिए ओवरड्राफ़्ट चला सकता है; आई.एस.एन. प्रसाद की अध्यक्षता वाली रिज़र्व बैंक की सलाहकार समिति ने सितंबर 2026 में इसे लगातार 10 दिनों और प्रति तिमाही 30 दिनों तक कसने का प्रस्ताव किया। कथन 3 ग़लत है: सीमाएँ रिज़र्व बैंक तय करता है, ऐसी समितियों की सलाह पर संशोधित कर; इस समिति ने कुल सीमा ₹61,008 करोड़ से बढ़ाकर ₹67,839 करोड़ करने और हर राज्य की सीमा व्यय के बजाय समायोजित राजस्व प्राप्तियों पर आधारित करने का प्रस्ताव किया।', concept_group_id = 'ca-t3-eco-states-wma-committee-prasad-overdraft', source_citation = 'Reserve Bank of India, Report of the Advisory Committee on Ways and Means Advances to State Governments (29 September 2026) and press release.', question_data = '{"statements": ["A State that has used up its WMA limit cannot obtain any further funds from the Reserve Bank.", "Before drawing WMA, a State can draw on a Special Drawing Facility against its investments in the Consolidated Sinking Fund.", "The WMA limits of the States are fixed by the Finance Commission."], "statements_hi": ["जिस राज्य ने अपनी डब्ल्यूएमए सीमा पूरी कर ली हो, वह रिज़र्व बैंक से और कोई राशि प्राप्त नहीं कर सकता।", "डब्ल्यूएमए लेने से पहले कोई राज्य समेकित निक्षेप निधि में अपने निवेश के बदले विशेष आहरण सुविधा का उपयोग कर सकता है।", "राज्यों की डब्ल्यूएमए सीमाएँ वित्त आयोग तय करता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "b", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "c", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "d", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-states-wma-committee-prasad-overdraft') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Growth, Development, Poverty & Planning', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about the Global Innovation Index:', body_hi = 'वैश्विक नवाचार सूचकांक के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 3 is correct. India, 38th of 139 economies in 2026 as in 2025 (up from 48th in 2020), led the lower-middle-income group and the economies of Central and Southern Asia; Switzerland again topped the index. Statement 2 is wrong: the index is published by the World Intellectual Property Organization, a UN specialised agency. Statement 1 is wrong: it combines an input sub-index (institutions, human capital and research, infrastructure, market and business sophistication) with an output sub-index (knowledge and technology outputs, creative outputs); India ranks higher on outputs than on inputs, which is why raising research spending and the quality of institutions are the usual prescriptions.', explanation_hi = 'केवल कथन 3 सही है। 2026 में, 2025 की तरह, 139 अर्थव्यवस्थाओं में 38वें स्थान पर (2020 के 48वें से ऊपर) भारत निम्न-मध्यम आय समूह और मध्य तथा दक्षिणी एशिया की अर्थव्यवस्थाओं में अग्रणी रहा; स्विट्ज़रलैंड फिर शीर्ष पर रहा। कथन 2 ग़लत है: सूचकांक संयुक्त राष्ट्र की विशिष्ट एजेंसी विश्व बौद्धिक संपदा संगठन प्रकाशित करता है। कथन 1 ग़लत है: यह एक निवेश उप-सूचकांक (संस्थाएँ, मानव पूँजी और अनुसंधान, अवसंरचना, बाज़ार और व्यावसायिक परिष्कार) को एक परिणाम उप-सूचकांक (ज्ञान और प्रौद्योगिकी परिणाम, रचनात्मक परिणाम) से जोड़ता है; भारत निवेशों की तुलना में परिणामों पर ऊँचा है, इसी कारण अनुसंधान व्यय और संस्थाओं की गुणवत्ता बढ़ाना सामान्य सुझाव हैं।', concept_group_id = 'ca-t3-eco-gii-2026-wipo-38-lower-middle-income', source_citation = 'World Intellectual Property Organization, Global Innovation Index 2026; Ministry of Commerce and Industry / PIB, India''s ranking in the Global Innovation Index.', question_data = '{"statements": ["It ranks economies on innovation inputs alone, such as institutions, human capital and infrastructure.", "It is published by the World Economic Forum.", "In its 2026 edition India ranked first among the lower-middle-income economies."], "statements_hi": ["यह अर्थव्यवस्थाओं को केवल नवाचार निवेशों, जैसे संस्थाओं, मानव पूँजी और अवसंरचना, पर क्रमबद्ध करता है।", "इसे विश्व आर्थिक मंच प्रकाशित करता है।", "इसके 2026 के संस्करण में भारत निम्न-मध्यम आय वाली अर्थव्यवस्थाओं में पहले स्थान पर रहा।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "3 only", "body_hi": "केवल 3", "isCorrect": true}, {"id": "c", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": false}, {"id": "d", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-gii-2026-wipo-38-lower-middle-income') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Industry, Infrastructure, Energy & Services', type = 'statement_based', difficulty = 'medium', body = 'With reference to Compressed Biogas (CBG) in India, consider the following statements:', body_hi = 'भारत में संपीडित बायोगैस (सीबीजी) के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three statements are correct. Biogas from crop residue, cattle dung, press mud and municipal organic waste is cleaned of carbon dioxide and hydrogen sulphide and compressed, giving a fuel of over 90 per cent methane. Under the CBG blending obligation, mandatory from 2025-26, city gas distribution entities must blend a share of CBG in the CNG and piped gas they sell, rising to 5 per cent by 2028-29, which gives plants an assured buyer. The digestate, sold as fermented organic manure, gets Market Development Assistance of ₹1,500 a tonne. The national unified scheme GOBARdhan, approved in August 2026 with ₹23,731 crore for 2026-27 to 2035-36, brings these and the earlier SATAT initiative together, aiming at a nearly ten-fold rise in CBG output: it cuts gas imports, gives farmers an alternative to burning stubble and turns waste into fuel.', explanation_hi = 'तीनों कथन सही हैं। फ़सल अवशेष, गोबर, प्रेस मड और नगरीय जैविक कचरे से बनी बायोगैस से कार्बन डाइऑक्साइड और हाइड्रोजन सल्फ़ाइड हटाकर उसे संपीडित किया जाता है, जिससे 90 प्रतिशत से अधिक मीथेन वाला ईंधन मिलता है। 2025-26 से अनिवार्य सीबीजी सम्मिश्रण दायित्व के अंतर्गत शहरी गैस वितरण इकाइयों को अपने बेचे सीएनजी और पाइप गैस में सीबीजी का एक अंश मिलाना होता है, जो 2028-29 तक 5 प्रतिशत तक बढ़ता है, इससे संयंत्रों को सुनिश्चित ख़रीदार मिलता है। बचा हुआ पाचित पदार्थ, जो किण्वित जैविक खाद के रूप में बिकता है, ₹1,500 प्रति टन की बाज़ार विकास सहायता पाता है। अगस्त 2026 में 2026-27 से 2035-36 के लिए ₹23,731 करोड़ के साथ स्वीकृत राष्ट्रीय एकीकृत योजना गोबरधन इन्हें और पहले की सतत पहल को साथ लाती है, सीबीजी उत्पादन में लगभग दस गुना वृद्धि के लक्ष्य से: यह गैस आयात घटाती है, किसानों को पराली जलाने का विकल्प देती है और कचरे को ईंधन बनाती है।', concept_group_id = 'ca-t3-eco-gobardhan-cbg-ten-years-cgd-offtake', source_citation = 'Cabinet decision and PIB, GOBARdhan -- National Unified Scheme for Compressed Biogas (August 2026); Ministry of Petroleum and Natural Gas, CBG blending obligation and SATAT initiative; Department of Fertilizers, Market Development Assistance for fermented organic manure.', question_data = '{"statements": ["City gas distribution entities are obliged to blend a rising share of CBG in the gas they supply.", "Fermented organic manure produced in CBG plants is eligible for Market Development Assistance.", "It is upgraded biogas, mostly methane, that can replace natural gas in vehicles and kitchens."], "statements_hi": ["शहरी गैस वितरण इकाइयों को अपनी आपूर्ति की गैस में सीबीजी का बढ़ता अंश मिलाना अनिवार्य है।", "सीबीजी संयंत्रों में बनी किण्वित जैविक खाद बाज़ार विकास सहायता की पात्र है।", "यह उन्नत बायोगैस है, अधिकांशतः मीथेन, जो वाहनों और रसोई में प्राकृतिक गैस का स्थान ले सकती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "b", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": false}, {"id": "c", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-gobardhan-cbg-ten-years-cgd-offtake') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Industry, Infrastructure, Energy & Services', type = 'statement_based', difficulty = 'medium', body = 'Floating solar plants with battery storage are being set up on reservoirs under the Pradhan Mantri Surya Sarovar Yojana. Consider the following statements about such plants:', body_hi = 'प्रधानमंत्री सूर्य सरोवर योजना के अंतर्गत जलाशयों पर बैटरी भंडारण सहित तैरते सौर संयंत्र लगाए जा रहे हैं। ऐसे संयंत्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three statements are correct. Floating panels use the surface of existing reservoirs and industrial ponds, so no farmland or forest is taken; solar cells lose efficiency as they heat up, and the water beneath keeps them cooler, while the cover reduces evaporation, which matters for drinking-water and irrigation reservoirs. Solar output peaks at midday, but demand peaks in the evening, so the scheme of the Ministry of New and Renewable Energy pairs 5,000 MW of floating solar with at least 10,000 MWh of storage, two hours at full output. The Solar Energy Corporation of India runs it, awarding projects through tariff-based competitive bidding.', explanation_hi = 'तीनों कथन सही हैं। तैरते पैनल मौजूदा जलाशयों और औद्योगिक तालाबों की सतह का उपयोग करते हैं, इसलिए कोई कृषि भूमि या वन नहीं लिया जाता; सौर सेल गर्म होने पर दक्षता खोते हैं, और नीचे का पानी उन्हें ठंडा रखता है, जबकि आवरण वाष्पीकरण घटाता है, जो पेयजल और सिंचाई जलाशयों के लिए महत्त्वपूर्ण है। सौर उत्पादन दोपहर में चरम पर होता है, पर माँग शाम को, इसलिए नवीन और नवीकरणीय ऊर्जा मंत्रालय की यह योजना 5,000 मेगावाट तैरते सौर को कम से कम 10,000 मेगावाट-घंटे के भंडारण से जोड़ती है, जो पूरे उत्पादन पर दो घंटे है। भारतीय सौर ऊर्जा निगम इसे चलाता है और परियोजनाएँ टैरिफ़-आधारित प्रतिस्पर्धी बोली से देता है।', concept_group_id = 'ca-t3-eco-surya-sarovar-floating-solar-storage-seci', source_citation = 'Cabinet decision and PIB, Pradhan Mantri Surya Sarovar Yojana (July 2026); Ministry of New and Renewable Energy; Solar Energy Corporation of India.', question_data = '{"statements": ["With storage attached, they can keep supplying power into the evening peak after the sun has set.", "They avoid the need to acquire land for the panels.", "The water keeps the panels cooler, which improves their output, while the panels reduce evaporation from the reservoir."], "statements_hi": ["संलग्न भंडारण के साथ वे सूर्यास्त के बाद शाम की चरम माँग में भी बिजली देते रह सकते हैं।", "इनसे पैनलों के लिए भूमि अधिग्रहण की आवश्यकता नहीं रहती।", "पानी पैनलों को ठंडा रखता है, जिससे उनका उत्पादन बढ़ता है, जबकि पैनल जलाशय से वाष्पीकरण घटाते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": true}, {"id": "b", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": false}, {"id": "d", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-surya-sarovar-floating-solar-storage-seci') returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'External Sector & International Institutions', type = 'assertion_reason', difficulty = 'medium', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statement I is correct but Statement II is incorrect. At their summit in Melbourne in July 2026, India and Australia settled the Administrative Arrangement under their 2014 civil nuclear agreement, opening the way to long-term commercial supplies of Australian uranium for peaceful use, kept under IAEA safeguards; India also buys from Kazakhstan, the largest producer, and Canada, because its own ore is limited and of low grade while it targets 100 GW of nuclear capacity by 2047. Statement II is wrong: thorium is fertile, not fissile, so no enrichment can make it a fuel by itself; it must first absorb neutrons in a reactor to become fissile uranium-233. That is why India''s three-stage programme runs on natural uranium first and on plutonium-fuelled fast breeders second, and can use thorium on a large scale only in its third stage.', explanation_hi = 'कथन I सही है पर कथन II ग़लत है। जुलाई 2026 में मेलबर्न में अपने शिखर सम्मेलन में भारत और ऑस्ट्रेलिया ने अपने 2014 के असैन्य परमाणु समझौते के अंतर्गत प्रशासनिक व्यवस्था तय की, जिससे शांतिपूर्ण उपयोग के लिए ऑस्ट्रेलियाई यूरेनियम की दीर्घकालिक वाणिज्यिक आपूर्ति का मार्ग खुला, आईएईए सुरक्षा उपायों के अधीन; भारत सबसे बड़े उत्पादक कज़ाख़स्तान और कनाडा से भी ख़रीदता है, क्योंकि उसका अपना अयस्क सीमित और निम्न श्रेणी का है, जबकि उसका लक्ष्य 2047 तक 100 गीगावाट परमाणु क्षमता है। कथन II ग़लत है: थोरियम उर्वर है, विखंडनीय नहीं, इसलिए कोई संवर्धन उसे अपने-आप ईंधन नहीं बना सकता; उसे पहले रिएक्टर में न्यूट्रॉन सोखकर विखंडनीय यूरेनियम-233 बनना होता है। इसी कारण भारत का त्रि-चरणीय कार्यक्रम पहले प्राकृतिक यूरेनियम पर और दूसरे चरण में प्लूटोनियम-ईंधन वाले फ़ास्ट ब्रीडरों पर चलता है, और थोरियम का बड़े पैमाने पर उपयोग केवल तीसरे चरण में कर सकता है।', concept_group_id = 'ca-t3-eco-australia-uranium-iaea-kazakhstan-2014', source_citation = 'Ministry of External Affairs and PIB factsheet, Third India-Australia Annual Summit (Melbourne, July 2026); India-Australia Civil Nuclear Cooperation Agreement (2014); Department of Atomic Energy, three-stage nuclear power programme.', question_data = '{"assertion": "India has been arranging long-term supplies of uranium from abroad, including from Australia, although it has some of the world''s largest reserves of thorium.", "assertion_hi": "भारत विदेश से, ऑस्ट्रेलिया सहित, यूरेनियम की दीर्घकालिक आपूर्ति की व्यवस्था करता रहा है, यद्यपि उसके पास विश्व के सबसे बड़े थोरियम भंडारों में से कुछ हैं।", "reason": "Thorium can be used directly as reactor fuel once it has been enriched, as uranium is.", "reason_hi": "थोरियम को यूरेनियम की तरह संवर्धित कर लेने पर सीधे रिएक्टर ईंधन के रूप में उपयोग किया जा सकता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference", "ca_window": "2026-Q3"}'::jsonb, options = '[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('ca-t3-eco-australia-uranium-iaea-kazakhstan-2014') returning concept_group_id;
commit;
